import ast,pathlib
for p in pathlib.Path('.').rglob('*.py'):
 try: t=ast.parse(p.read_text())
 except (SyntaxError,UnicodeError): continue
 for n in ast.walk(t):
  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id in ('Linear','LinearFP16'):
   print(str(p)+':'+str(n.lineno)+' '+ast.get_source_segment(p.read_text(),n))

